mapper.select:
select s.*, d.name deptName, c.name className
from student s
left join dept d on s.dept_id = d.id
left join clss c on s.class_id = c.id

  s.name like concat('%',#{name},'%')
  and s.gender = #{gender} 
  and s.enrollment_year between #{begin} and #{end}
  and s.dept_id = #{deptId} 
  and s.class_id = #{classId} 

order by s.update_time desc

mapper.update:
UPDATE student
dept_id = #{deptId}, class_id = #{classId}, name = #{name}, gender = #{gender}, image = #{image}, enrollment_year = #{enrollmentYear}, update_time = #{updateTime}
WHERE id = #{id}
